// Word lists for Vowel Play, generated by scripts/buildVowelWords.ts (do not edit the JSON by hand).
import data from "./vowelWords.json";

/** Topics with at least 40 fair names; the title is the only hint players get. */
export const VOWEL_TOPICS: { id: string; title: string }[] = data.topics;

const WORDS = data.words as Record<string, string[]>;

/** Names for a topic; empty for an unknown topic. */
export function wordsFor(topic: string): string[] {
  return Object.hasOwn(WORDS, topic) ? WORDS[topic]! : [];
}
